import { useState } from "react";
import DATA from "../data.json";
import { LineChart, StepTokensChart, ThroughputBars, TimeBreakdown, TimeSplit } from "../components/charts.jsx";
import { CompareTable, RunsTable, TaskGrid } from "../components/tables.jsx";
import { Legend, Section, Stat } from "../components/ui.jsx";
import { fmt, mean, SERIES } from "../lib/format.js";

// data.json is generated by the backend (`uv run agentic-export`); never edit it by hand.

const pct = (xs, q) => xs[Math.floor(q * (xs.length - 1))];

function KeyNumbers({ exp }) {
  const runs = exp.runs;
  const st = exp.stats ? Object.values(exp.stats) : [];
  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
      <Stat label="Repeated prefix" unit="%" hint="of each prompt (steps ≥ 1)"
            value={fmt(st.length ? mean(st.map((v) => v["repeated_prefix_%_steps_ge1"])) : mean(runs.map((r) => r["prefix_reuse_%"])), 0)} />
      <Stat label="Served from cache" unit="%" hint="prompt tokens" value={fmt(mean(runs.map((r) => r["cached_tok_%"])), 0)} />
      {st.length
        ? <Stat label="Time in prefill" unit="%" hint="processing the prompt (TTFT)"
                value={fmt(mean(st.map((v) => v["time_split_%"]["prefill (TTFT)"])), 0)} />
        : <Stat label="Time in the LLM" unit="%" hint="vs. tools and overhead" value={fmt(mean(runs.map((r) => r["llm_%"])), 0)} />}
      <Stat label="Accuracy" unit="%" hint={`mean of ${runs.length} runs`} value={fmt(100 * mean(runs.map((r) => r.accuracy)), 0)} />
    </div>
  );
}

function Experiment({ exp }) {
  const ex = exp.example;
  const manyTasks = Object.keys(exp.per_task || {}).length > 20;
  const first3 = (obj) => Object.entries(obj).slice(0, 3);
  return (
    <div className="space-y-6">
      {exp.description && <p className="secondary max-w-3xl">{exp.description}</p>}
      <KeyNumbers exp={exp} />

      <div className="grid lg:grid-cols-2 gap-6">
        <Section title="Prompt grows, cache follows" subtitle={<><span className="mono">{ex.run}/{ex.task_id}</span> · {ex.model} · "{ex.question}"</>}>
          <Legend items={[["Prompt tokens", "var(--series-1)"], ["Cached tokens", "var(--series-2)"]]} />
          <div className="mt-2"><StepTokensChart steps={ex.steps} /></div>
          <p className="text-xs muted mt-1">Step number on the x-axis. ✂ = server truncated the context.</p>
        </Section>
        <Section title="Where the time goes" subtitle="Share of total task time, per run">
          {exp.time_split ? <TimeSplit split={exp.time_split} /> : <TimeBreakdown runs={exp.runs} />}
        </Section>
      </div>

      {exp.compare && (
        <Section title="Serving comparison">
          <CompareTable rows={exp.compare} />
          {exp.compare.some((r) => r.tasks_per_min) && (
            <div className="mt-5">
              <div className="text-sm font-medium mb-2">Throughput (tasks per minute)</div>
              <ThroughputBars rows={exp.compare} />
            </div>
          )}
        </Section>
      )}

      {exp.growth && (
        <div className="grid lg:grid-cols-2 gap-6">
          <Section title="Context grows every step" subtitle="Median prompt tokens per step; band = 25th-75th percentile">
            <Legend items={first3(exp.growth).map(([r], i) => [r, SERIES[i]])} />
            <LineChart band xLabel="Step" yLabel="Prompt tokens"
                       series={first3(exp.growth).map(([name, pts]) => ({ name, points: pts.map((p) => ({ x: p.step, y: p.p50, lo: p.p25, hi: p.p75 })) }))} />
          </Section>
          <Section title="Task latency CDF"
                   subtitle={Object.entries(exp.latency).map(([r, xs]) => `${r}: P50 ${fmt(pct(xs, 0.5), 0)}s, P95 ${fmt(pct(xs, 0.95), 0)}s`).join(" · ")}>
            <Legend items={first3(exp.latency).map(([r], i) => [r, SERIES[i]])} />
            <LineChart stepLine yMax={100} xLabel="Task latency (s)" yLabel="% of tasks" fmtY={(v) => `${v}%`} fmtX={(v) => `${Math.round(v)}`}
                       series={first3(exp.latency).map(([name, xs]) => ({ name, points: xs.map((v, i) => ({ x: v, y: Math.round((100 * (i + 1)) / xs.length) })) }))} />
          </Section>
        </div>
      )}

      <Section title="All runs"><RunsTable runs={exp.runs} /></Section>
      {!manyTasks && <Section title="Correct answers per task"><TaskGrid perTask={exp.per_task} /></Section>}
      <p className="text-xs muted">Exported {exp.exported}. Page data updated {DATA.updated}.</p>
    </div>
  );
}

export default function Results() {
  const exps = DATA.experiments || [];
  const [sel, setSel] = useState(exps.length ? exps[exps.length - 1].id : null);
  const exp = exps.find((e) => e.id === sel);
  if (!exp) {
    return <div className="card p-6 secondary">No results exported yet. Run <code className="mono">uv run agentic-export</code> in <code className="mono">backend/</code>.</div>;
  }
  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-2">
        {exps.map((e) => (
          <button key={e.id} onClick={() => setSel(e.id)}
                  className={`px-3 py-1.5 rounded-lg text-sm border cursor-pointer ${e.id === sel ? "tab-active font-medium" : "border-transparent secondary"}`}>
            {e.title}
          </button>
        ))}
      </div>
      <Experiment key={exp.id} exp={exp} />
    </div>
  );
}
